{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.website_marketplace_fact_items as With Product_Level_Data as ( select om.* ,od.site_product_name ,od.product_name ,od.product_qty ,od.product_pack ,od.cost_price ,od.selling_price ,od.total_price ,od.is_pack ,od.status ,od.prod_returned_date ,od.prod_return_qty ,od.returnreason ,od.product_id ,od.product_master_id ,od.prod_vat ,od.ship_vat ,od.prod_ship ,od.other_vat_charge ,od.prod_refund_amount ,od.prod_refund_vat ,od.primary_cat_id ,od.product_code as sku ,del_country as delivery_country ,case when upper(`pg_status`) = \'Y\' AND pg.`mpg_id` = 11 then \'MARKETPLACE\' else \'WEBSITE\' end as Business_Segment from cc_comfort_db.order_master om left join cc_comfort_db.order_details od on od.order_id = om.order_id left join ( SELECT * FROM `cc_comfort_db.payment_gateways` qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on lower(pg.gateway_name) = lower(om.payment_gateway) where od.status != 0 ) select pld.order_id ,pld.order_id as reference_code ,coalesce(del_mobile,bill_mobile) as phone ,cast(null as string) as email ,cast(null as string) as name ,date(pld.order_date) as order_date ,timestamp(pld.order_date) as order_timestamp ,date(pld.order_modified_date) as order_modified_date ,currency_name_customer currency_code ,coalesce(del_city,bill_city) as City ,coalesce(del_state,bill_State) as State ,coalesce(del_zipcode,bill_zipcode) zipcode ,upper(coalesce(del_country,bill_country)) as country_name ,pld.payment_gateway ,delivery_country ,courier_name ,pld.courier_id ,tracking_number as awb ,site_product_name ,sku ,product_name ,product_qty ,product_pack ,cost_price ,selling_price ,total_price ,is_pack ,status ,prod_returned_date ,prod_return_qty ,returnreason ,product_id ,pld.product_master_id ,prod_vat ,ship_vat ,prod_ship ,other_vat_charge ,prod_refund_amount ,prod_refund_vat ,primary_cat_id ,upper(cd.cd_name) product_category_local ,upper(cm.cm_name) product_category ,pg.pg_status ,pg.mpg_id ,pg.merchant_fee ,pg.marketplaces_commission ,Business_Segment ,case when Business_Segment = \'WEBSITE\' then \'WEBSITE\' else pgmm.Marketplace end as Marketplace ,case when Business_Segment = \'WEBSITE\' then dnm.brand else pmi.pb_name end as Brand ,pg_category.mpg_name as mpg_Name_Category ,d.id as domain_id ,upper(d.domain_division) domain_division ,date(op.paid_date) as paid_date ,date(op.dispatched_date) as dispatched_date ,date(op.decline_date) as decline_date ,op.decline_reason ,date(op.refund_date) as refund_date ,op.refund_reason ,op.refund_amount ,op.refund_gateway ,csg.Status_Name Order_Status ,d.name as domain_name ,d.default_country_code as Region from Product_Level_Data pld left join( select * from cc_comfort_db.category_domain qualify ROW_NUMBER() over(partition by ifnull(cd_id,0) order by 1) = 1 )cd on cd.cd_id = pld.primary_cat_id left join ( select * from `cc_comfort_db.category_master` qualify ROW_NUMBER() over(partition by ifnull(cm_id,0) order by 1) = 1 )cm on cm.cm_id = cd.cd_cm_id left join ( SELECT * FROM `cc_comfort_db.payment_gateways` qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on lower(pg.gateway_name) = lower(pld.payment_gateway) left join ( select payment_gateway,Marketplace from `MAPLEMONK.PaymentGateway_to_Marketplace_mapping` qualify ROW_NUMBER() over(partition by ifnull(payment_gateway,\'\') order by 1) = 1 )pgmm on lower(pgmm.payment_gateway) = lower(pld.payment_gateway) left join ( select * from powerbi-425707.cc_comfort_db.master_payment_gateway qualify ROW_NUMBER() over(partition by (ifnull(mpg_id,0)) order by 1) = 1 )pg_category on pg_category.mpg_id = pg.mpg_id left join ( select domain_division,name,id,default_country_code from cc_comfort_db.domains qualify ROW_NUMBER() over(partition by (ifnull(id,0)) order by 1) = 1 )d on pld.domain_id = d.id left join ( select * from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on op.order_id = pld.order_id left join ( select * from maplemonk.current_status_mapping csg qualify ROW_NUMBER() over(partition by ifnull(cast(id as int64),0) order by 1) = 1 )csg on cast(csg.id as string) = cast(pld.current_status as string) left join ( select Domain_Name,brand from `MAPLEMONK.Domain_Marketplace_Mapping` qualify ROW_NUMBER() over(partition by ifnull(Domain_Name,\'\') order by 1) = 1 and lower(Marketplace) = \'website\' )dnm on lower(dnm.Domain_Name) = lower(d.name) left join ( select product_master_id ,pb_name from cc_comfort_db.products_master pm left join cc_comfort_db.product_brands pb on lower(cast(pm.pm_pb_brand_id as string)) = lower(cast(pb.pb_brand_id as string)) qualify row_number() over(partition by product_master_id order by 1) = 1 )pmi on lower(cast(pmi.product_master_id as string)) = lower(cast(pld.product_master_id as string)) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

